package com.jgeted.sagadyssey.social.religion.life;

import com.jgeted.sagadyssey.core.MinecraftApi;

import com.jgeted.sagadyssey.knowledge.*;
import com.jgeted.sagadyssey.npc.entity.NpcBase;
import com.jgeted.sagadyssey.social.institution.*;
import com.jgeted.sagadyssey.social.religion.*;
import com.mojang.brigadier.arguments.*;
import com.mojang.brigadier.context.CommandContext;
import com.mojang.brigadier.exceptions.CommandSyntaxException;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.EntityArgument;
import net.minecraft.commands.arguments.coordinates.BlockPosArgument;
import net.minecraft.network.chat.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
import java.util.*;

/** Ordinary menus disclose local public invitations and lawful records, never hidden truth. */
@EventBusSubscriber(modid="sagadyssey")
public final class ChurchLifeCommand {
    @SubscribeEvent public static void register(RegisterCommandsEvent e){var root=Commands.literal("church");
        root.then(Commands.literal("here").executes(c->safe(c,()->{
            var p=c.getSource().getPlayerOrException();var d=ChurchLifeData.get(p.level().getServer());UUID person=ReligionService.currentCharacter(p);if(person==null){c.getSource().sendFailure(Component.literal("当前没有可用的存活人物身份。"));return 0;}long now=p.level().getGameTime();
            for(var t:ReligionData.get(p.level().getServer()).temples())if(ReligionService.near(p,t)){
                c.getSource().sendSuccess(()->Component.literal(t.name()+"：本地公开日程与本人可查文书；目录不代表掌握全文。"),false);
                for(var a:d.activities())if(a.temple().equals(t.id())&&!a.stage().closed()&&a.invited().contains(person))c.getSource().sendSuccess(()->Component.literal("[同意参加 "+a.kind()+"] 时间 "+a.scheduled()+"–"+a.deadline()).withStyle(style->style.withClickEvent(new ClickEvent.SuggestCommand("/saga church join "+a.id()))),false);
                for(String r:ChurchLifeService.index(p.level().getServer(),t,p))c.getSource().sendSuccess(()->Component.literal(r),false);
            }return 1;})));
        root.then(Commands.literal("join").then(Commands.argument("activity",StringArgumentType.word()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();ChurchLifeService.consent(p.level().getServer(),uuid(c,"activity"),p);c.getSource().sendSuccess(()->Component.literal("已登记本人的同意；仍需实际到场，离开时不会被记为参加。"),false);return 1;}))));
        root.then(Commands.literal("read").then(Commands.argument("record",StringArgumentType.word()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();String text=ChurchLifeService.read(p.level().getServer(),uuid(c,"record"),p);c.getSource().sendSuccess(()->Component.literal(text),false);return 1;}))));
        root.then(Commands.literal("known").then(Commands.argument("temple",StringArgumentType.word()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();UUID person=ReligionService.currentCharacter(p);if(person==null){c.getSource().sendFailure(Component.literal("当前没有可用的存活人物身份。"));return 0;}int count=0;for(var b:KnowledgeStateData.get(p.level().getServer()).beliefsAbout(person,uuid(c,"temple")))if(b.key().predicate().startsWith("church.")){c.getSource().sendSuccess(()->Component.literal(b.displayValue()+"（来源="+b.sourceLabel()+"；时间="+b.lastConfirmedAt()+"；可信度="+b.confidence()+"）"),false);count++;}if(count==0)c.getSource().sendSuccess(()->Component.literal("本人尚无可确认的教会生活记录；后台目录不会代替亲历或查阅。"),false);return count;}))));
        root.then(Commands.literal("leave").then(Commands.argument("activity",StringArgumentType.word()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();var d=ChurchLifeData.get(p.level().getServer());d.put(d.activity(uuid(c,"activity")).decline(ReligionService.character(p)));c.getSource().sendSuccess(()->Component.literal("本人已撤回同意；不会继续被算作参加者。"),false);return 1;}))));
        root.then(Commands.literal("complain").then(Commands.argument("record",StringArgumentType.word()).then(Commands.argument("forum",StringArgumentType.word()).then(Commands.argument("allegation",StringArgumentType.greedyString()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();var v=ChurchLifeService.complain(p.level().getServer(),p,uuid(c,"record"),uuid(c,"forum"),StringArgumentType.getString(c,"allegation"));c.getSource().sendSuccess(()->Component.literal("本地申诉已立案 "+v.id()+"；文书是可质疑证据，不等于有罪判决。"),false);return 1;}))))));
        root.then(Commands.literal("catalogue").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("temple",StringArgumentType.word()).then(Commands.argument("slot",IntegerArgumentType.integer(0,26)).then(Commands.argument("access",StringArgumentType.word()).executes(c->safe(c,()->{var s=c.getSource().getServer();var r=ChurchLifeService.catalogue(s,temple(c),IntegerArgumentType.getInteger(c,"slot"),ChurchRecord.Access.valueOf(StringArgumentType.getString(c,"access")));c.getSource().sendSuccess(()->Component.literal("真实成书登记 "+r.id()+"；未生成教材、赋予知识或验证内容为真"),false);return 1;}))))));
        var duration=Commands.argument("duration",IntegerArgumentType.integer(20,24000)).executes(c->safe(c,()->{
            var s=c.getSource().getServer();var entities=EntityArgument.getEntities(c,"participants");var people=new ArrayList<UUID>();for(var entity:entities){if(!(entity instanceof net.minecraft.world.entity.LivingEntity l))throw new IllegalArgumentException("participants must be living characters");people.add(ReligionService.character(l));}
            long now=s.overworld().getGameTime();var a=ChurchLifeService.schedule(s,UUID.randomUUID(),temple(c),ChurchActivity.Kind.valueOf(StringArgumentType.getString(c,"kind")),BlockPosArgument.getLoadedBlockPos(c,"venue"),optionalUuid(c,"subject"),optionalUuid(c,"source"),people,IntegerArgumentType.getInteger(c,"minimum"),now+IntegerArgumentType.getInteger(c,"delay"),now+IntegerArgumentType.getInteger(c,"delay")+IntegerArgumentType.getInteger(c,"window"),IntegerArgumentType.getInteger(c,"duration"));
            c.getSource().sendSuccess(()->Component.literal("测试者创建邀请 "+a.id()+"；参与者尚未同意，不把后台设定记成玩家知识"),false);return 1;}));
        root.then(Commands.literal("schedule").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("temple",StringArgumentType.word()).then(Commands.argument("kind",StringArgumentType.word()).then(Commands.argument("venue",BlockPosArgument.blockPos()).then(Commands.argument("subject",StringArgumentType.word()).then(Commands.argument("source",StringArgumentType.word()).then(Commands.argument("participants",EntityArgument.entities()).then(Commands.argument("minimum",IntegerArgumentType.integer(0,16)).then(Commands.argument("delay",IntegerArgumentType.integer(0,168000)).then(Commands.argument("window",IntegerArgumentType.integer(200,24000)).then(duration)))))))))));
        root.then(Commands.literal("npc-consent").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("activity",StringArgumentType.word()).then(Commands.argument("npc",EntityArgument.entity()).executes(c->safe(c,()->{if(!(EntityArgument.getEntity(c,"npc") instanceof NpcBase n))throw new IllegalArgumentException("只允许测试者显式设置 NPC 同意，不能替玩家签名");ChurchLifeService.consent(MinecraftApi.server(n),uuid(c,"activity"),n);return 1;})))));
        root.then(Commands.literal("cancel").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("activity",StringArgumentType.word()).executes(c->safe(c,()->{var s=c.getSource().getServer();ChurchLifeService.cancel(s,ChurchLifeData.get(s).activity(uuid(c,"activity")),"测试者明确取消原活动");return 1;}))));
        root.then(Commands.literal("demo").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("temple",StringArgumentType.word()).executes(c->safe(c,()->{String text=ChurchLifeClientFixture.prepare(c.getSource().getPlayerOrException(),temple(c));c.getSource().sendSuccess(()->Component.literal(text),false);return 1;}))));
        root.then(Commands.literal("demo-status").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("temple",StringArgumentType.word()).executes(c->safe(c,()->{for(var text:ChurchLifeClientFixture.status(c.getSource().getPlayerOrException(),temple(c)))c.getSource().sendSuccess(()->Component.literal(text),false);return 1;}))));
        root.then(Commands.literal("death-report").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("npc",EntityArgument.entity()).then(Commands.argument("subject",StringArgumentType.word()).then(Commands.argument("statement",StringArgumentType.greedyString()).executes(c->safe(c,()->{if(!(EntityArgument.getEntity(c,"npc") instanceof NpcBase n))throw new IllegalArgumentException("真实听闻者需要 NPC");KnowledgeStateData.get(MinecraftApi.server(n)).testimony(n.getCharacterId(),com.jgeted.sagadyssey.worldsim.transfer.ContainerIds.named("explicit-test-witness"),new FactKey(uuid(c,"subject"),"church.death_report",""),StringArgumentType.getString(c,"statement"),PrecisionBand.CATEGORY,.6,n.level().getGameTime(),0,DisclosurePolicy.PRIVATE);return 1;}))))));
        root.then(Commands.literal("compact").then(Commands.argument("temple",StringArgumentType.word()).then(Commands.argument("type",StringArgumentType.word()).then(Commands.argument("partner",StringArgumentType.word()).then(Commands.argument("ticks",IntegerArgumentType.integer(200,168000)).then(Commands.argument("terms",StringArgumentType.greedyString()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();var partner=new com.jgeted.sagadyssey.worldsim.rights.SubjectRef(com.jgeted.sagadyssey.worldsim.rights.SubjectRef.SubjectType.valueOf(StringArgumentType.getString(c,"type")),uuid(c,"partner"));var v=ChurchLifeService.propose(p.level().getServer(),UUID.randomUUID(),temple(c),partner,p,p.level().getGameTime()+IntegerArgumentType.getInteger(c,"ticks"),StringArgumentType.getString(c,"terms"));c.getSource().sendSuccess(()->Component.literal("具体地方协定草案 "+v.id()+"；双方须分别签署，未改变阵营声望或转移物资"),false);return 1;}))))))));
        root.then(Commands.literal("sign").then(Commands.argument("compact",StringArgumentType.word()).then(Commands.argument("church",BoolArgumentType.bool()).executes(c->safe(c,()->{var p=c.getSource().getPlayerOrException();var v=ChurchLifeService.sign(p.level().getServer(),uuid(c,"compact"),p,BoolArgumentType.getBool(c,"church"));c.getSource().sendSuccess(()->Component.literal("本人签署记录已保存；双方均签署="+v.active(p.level().getGameTime())),false);return 1;})))));
        root.then(Commands.literal("calendar").requires(s->MinecraftApi.hasPermission(s, 2)).then(Commands.argument("temple",StringArgumentType.word()).then(Commands.argument("participants",EntityArgument.entities()).then(Commands.argument("interval",IntegerArgumentType.integer(200,168000)).then(Commands.argument("count",IntegerArgumentType.integer(1,14)).executes(c->safe(c,()->{var s=c.getSource().getServer();var t=temple(c);var people=new ArrayList<UUID>();for(var x:EntityArgument.getEntities(c,"participants")){if(!(x instanceof net.minecraft.world.entity.LivingEntity l))throw new IllegalArgumentException("living participants required");people.add(ReligionService.character(l));}var v=new ChurchLifeData.Calendar(UUID.randomUUID(),t.id(),t.counter(),people,1,IntegerArgumentType.getInteger(c,"interval"),s.overworld().getGameTime()+40,0,IntegerArgumentType.getInteger(c,"count"));ChurchLifeData.get(s).put(v);c.getSource().sendSuccess(()->Component.literal("本地仪式日程 "+v.id()+"；每次单独邀请、核验同意和到场，最多 14 次后需重新安排"),false);return 1;})))))));
        root.then(Commands.literal("audit").requires(s->MinecraftApi.hasPermission(s, 2)).executes(c->safe(c,()->{var d=ChurchLifeData.get(c.getSource().getServer());for(var a:d.activities())c.getSource().sendSuccess(()->Component.literal("活动 "+a.id()+" "+a.kind()+" "+a.stage()+" host="+a.host()+" consent="+a.consent().size()+" work="+a.work()+" retry="+a.retryAt()+" reason="+a.detail()),false);for(var r:d.records())c.getSource().sendSuccess(()->Component.literal("文书 "+r.id()+" "+r.title()+" access="+r.access()+" author="+r.author()+" custodian="+r.custodian()+" time="+r.authoredAt()+" source="+r.source()+" confidence="+r.confidence()+"；后台默认不输出私密正文"),false);return 1;})));
        e.getDispatcher().register(Commands.literal("saga").then(root));}
    private static UUID uuid(CommandContext<CommandSourceStack> c,String name){return UUID.fromString(StringArgumentType.getString(c,name));}
    private static UUID optionalUuid(CommandContext<CommandSourceStack> c,String name){return StringArgumentType.getString(c,name).equals("none")?null:uuid(c,name);}
    private static TempleRecord temple(CommandContext<CommandSourceStack> c){return ReligionData.get(c.getSource().getServer()).temple(uuid(c,"temple"));}
    @FunctionalInterface private interface Action{int run()throws CommandSyntaxException;}
    private static int safe(CommandContext<CommandSourceStack> c,Action a)throws CommandSyntaxException{try{return a.run();}catch(RuntimeException ex){c.getSource().sendFailure(Component.literal("教会生活操作未完成："+ex.getMessage()));return 0;}}
}
